1	package org.springframework.samples.petclinic.util;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	
5	/**
6	 * Derives an owner's membership number '&lt;customerCode&gt;-M&lt;YY&gt;', where YY is the last two
7	 * digits of the registration date year (e.g. 'SYD-SMI-0007-M26'). The number combines the owner's
8	 * assigned customer code with the registration year, so it is only available once both have been set.
9	 */
10	public final class MembershipNumbers {
11	
12	    private MembershipNumbers() {
13	    }
14	
15	    /**
16	     * Return the owner's membership number, or null when either the customer code or the
17	     * registration date is absent.
18	     */
19	    public static String of(Owner owner) {
20	        if (owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
21	            return null;
22	        }
23	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
24	    }
25	}
