1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.DayOfWeek;
4	import java.time.LocalDate;
5	import java.util.Set;
6	
7	/**
8	 * Registration-date business rules shared by the owner-create pipeline. A registration
9	 * date must fall on a business day: when it lands on a Saturday, a Sunday or a listed
10	 * public holiday it rolls forward to the next non-holiday weekday. This applies to the
11	 * effective date whether it was supplied on the request or defaulted to the server's
12	 * current date, so both the step that stores the date ({@link ResolveRegistrationDate})
13	 * and the daily-limit guard ({@link EnsureDailyLimit}) derive the same adjusted day from
14	 * here.
15	 */
16	final class RegistrationDates {
17	
18	    /** Fixed public holidays skipped by the business-day roll. */
19	    private static final Set<LocalDate> HOLIDAYS = Set.of(
20	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
21	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"),
22	            LocalDate.parse("2026-12-28"));
23	
24	    private RegistrationDates() {
25	    }
26	
27	    /** Roll a weekend or public-holiday date forward to the next business day; a plain
28	     *  weekday is returned unchanged. */
29	    static LocalDate toBusinessDay(LocalDate date) {
30	        while (isWeekend(date) || HOLIDAYS.contains(date)) {
31	            date = date.plusDays(1);
32	        }
33	        return date;
34	    }
35	
36	    private static boolean isWeekend(LocalDate date) {
37	        return date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY;
38	    }
39	
40	    /**
41	     * The effective registration date: the supplied date, or the server's current date when
42	     * none was supplied, in either case rolled forward onto a business day.
43	     */
44	    static LocalDate effective(LocalDate supplied) {
45	        return toBusinessDay(supplied != null ? supplied : LocalDate.now());
46	    }
47	}
