1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * Resolves an owner's effective registration date on creation and stores it on the built
8	 * owner in place. A supplied date is kept, otherwise the server's current date is used; the
9	 * effective date is then rolled forward onto a business day (see {@link RegistrationDates}),
10	 * so a weekend date becomes the following Monday. Later steps (customer code, membership
11	 * number) read the stored, adjusted date.
12	 */
13	public class ResolveRegistrationDate {
14	
15	    public void service(@Val Owner owner) {
16	        owner.setRegistrationDate(RegistrationDates.effective(owner.getRegistrationDate()));
17	    }
18	}
