1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	
5	import net.officefloor.plugin.variable.Val;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.FutureRegistrationDateException;
8	
9	/**
10	 * Validates an optional registration date on an owner create request. The date is not
11	 * required: a null value is left untouched and later defaulted to the server's current date
12	 * (see {@link RegistrationDates}). When supplied it must not be later than the server date,
13	 * otherwise the request is rejected with {@link FutureRegistrationDateException} (400). Runs
14	 * before {@link BuildOwner} maps the body to an entity.
15	 */
16	public class ValidateRegistrationDate {
17	
18	    public void service(@Val OwnerFieldsDto request) throws FutureRegistrationDateException {
19	        LocalDate supplied = request.getRegistrationDate();
20	        if (supplied == null) {
21	            return;
22	        }
23	        LocalDate serverDate = LocalDate.now();
24	        if (supplied.isAfter(serverDate)) {
25	            throw new FutureRegistrationDateException(supplied, serverDate);
26	        }
27	    }
28	}
