3	import java.util.Locale;
4	import java.util.Set;
5	
6	/**
7	 * The owner customer-code identity, formatted {@code <REGION>-<HASH8>}: the region code
8	 * derived from the postcode, then the first eight upper-case hex characters of the SHA-256
9	 * digest of the owner's normalized telephone followed by their last name. Every value built
10	 * from the identity (membership number, check digit, locality) reads it back through here, so
11	 * the format lives in one place.
12	 */
13	public final class CustomerCode {
14	
15	    private static final char SEPARATOR = '-';
16	
17	    /** Number of leading hex characters of the digest kept as the identity's hash component. */
18	    private static final int HASH_LENGTH = 8;
19	
20	    private CustomerCode() {
21	    }
22	
23	    /**
24	     * Build the customer code {@code <region>-<HASH8>} for an owner in {@code region} whose
25	     * normalized telephone and last name hash to {@code HASH8}.
26	     */
27	    public static String of(String region, String normalizedTelephone, String lastName) {
28	        String hash8 = Sha256.hex(normalizedTelephone + lastName)
29	                .substring(0, HASH_LENGTH).toUpperCase(Locale.ROOT);
30	        return region + SEPARATOR + hash8;
31	    }
32	
33	    /**
34	     * De-duplicate {@code customerCode} against the codes already {@code taken}. When it is free
35	     * the code is returned unchanged; otherwise {@code -<n>} is appended with the smallest
36	     * {@code n} of 2 or more that yields a code no owner already holds.
37	     */
38	    public static String deduplicate(String customerCode, Set<String> taken) {
39	        if (!taken.contains(customerCode)) {
40	            return customerCode;
41	        }
42	        for (int n = 2; ; n++) {
43	            String candidate = customerCode + SEPARATOR + n;
44	            if (!taken.contains(candidate)) {
45	                return candidate;
46	            }
47	        }
48	    }
49	
50	    /**
51	     * The region component of {@code customerCode} (its identity locality), or
52	     * {@link CityRegions#UNKNOWN} when the code is absent or carries no region.
53	     */
54	    public static String regionOf(String customerCode) {
55	        if (customerCode == null) {
56	            return CityRegions.UNKNOWN;
57	        }
58	        int separator = customerCode.indexOf(SEPARATOR);
59	        String region = separator > 0 ? customerCode.substring(0, separator) : "";
60	        return region.isEmpty() ? CityRegions.UNKNOWN : region;
61	    }
62	}
